 ("أَبْني جُمَلًا عَنِ الْعيدِ 🔢","أَدَواتُ الرَّبْطِ",[["1️⃣","أَرْتَدي الْمَلابِسَ الْجَديدَةَ","ثُمَّ أَذْهَبُ لِلصَّلاةِ."],["2️⃣","آخُذُ الْعيدِيَّةَ","ثُمَّ أَبْدَأُ زِيارَةَ أَقاربي."],["3️⃣","أَنْتَظِرُ الْعيدَ كُلَّ عامٍ","لِآكُلَ الْحَلْوى وَأُزَيِّنَ الْبَيْتَ."]]),
 ("لِماذا","«لِماذا يَنْتَظِرُ الْوَلَدُ يَوْمَ الْعيدِ؟»",["(أ) سُؤالٌ عَنِ السَّبَبِ","(ب) سُؤالٌ عَنِ الزَّمَنِ","(ج) سُؤالٌ عَنِ الْمَكانِ"],"(أ): «لِماذا» أَداةُ اسْتِفْهامٍ لِلسُّؤالِ عَنِ السَّبَبِ."),
 ("أَتَحَدَّثُ عَنْ عيدي 🗣️","في يَوْمِ الْعيدِ أَذْهَبُ إِلى … وَأَلْبَسُ … وَآكُلُ …","نَموذَجٌ: في يَوْمِ الْعيدِ أَذْهَبُ إِلى بَيْتِ جَدّي، وَأَلْبَسُ مَلابِسَ جَديدَةً، وَآكُلُ الْكَعْكَ."),
 ("ماذا يَأْخُذُ الْوَلَدُ في الْعيدِ؟ 🤔",["(أ) الْحَلْوى وَالْعيدِيَّةَ","(ب) الْكُتُبَ","(ج) الْأَلْعابَ فَقَطْ"],"(أ): يَأْخُذُ الْحَلْوى وَالْعيدِيَّةَ مِنْ وَالِدَيْهِ."),
 dict(head="أَصِلُ رَحِمي",sana="أَزورُ أَقاربي في الْعيدِ، وَأَفْرَحُ بِلِقائِهِمْ.",fact="الْعيدِيَّةُ عادَةٌ جَميلَةٌ تُدْخِلُ الْفَرَحَ عَلى قُلوبِ الْأَطْفالِ في الْعيدِ.",dilemma="أُريدُ أَنْ أُنْفِقَ عيدِيَّتي كُلَّها عَلى الْحَلْوى… ماذا أَفْعَلُ؟",model="أَحْتَفِظُ بِجُزْءٍ مِنْها لِلِادِّخارِ، وَأُنْفِقُ جُزْءًا بِحِكْمَةٍ."),
 [["ماذا يَرْتَدي الْوَلَدُ صَباحَ الْعيدِ؟",["مَلابِسَ الْعيدِ الْجَديدَةَ","مَلابِسَ النَّوْمِ","الزِّيَّ الْمَدْرَسِيَّ"]],["إِلى أَيْنَ يَذْهَبُ مَعَ أُسْرَتِهِ؟",["إِلى الصَّلاةِ في الْمَسْجِدِ","إِلى الْمَدْرَسَةِ","إِلى السّوقِ"]],["مِمَّنْ يَأْخُذُ الْحَلْوى وَالْعيدِيَّةَ؟",["مِنْ والِدَيْهِ","مِنْ أَصْدِقائِهِ","مِنَ الْمُعَلِّمِ"]],["ماذا يَفْعَلُ بَعْدَ ذلِكَ؟",["يَزورُ أَقارِبَهُ وَأَصْدِقاءَهُ","يَنامُ","يَذْهَبُ لِلْمَدْرَسَةِ"]],["«كَعْكُ الْعيدِ» تَعْني:",["Eid cookies","Eid clothes","Eid money"]],["«لِماذا» نَسْأَلُ بِها عَنْ:",["السَّبَبِ","الزَّمَنِ","الْمَكانِ"]]],
